import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, uniform, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Build the capsule badge plane
  const geometry = new THREE.PlaneGeometry(0.8, 0.25);

  // Load the ceramic grain texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Color uniforms from the spec
  const accentColor = uniform(color('#ff2a38'));
  const surfaceColor = uniform(color('#0b0b10'));

  // TSL shader: ceramic grain base + accent edge glow on hover
  const materialNode = new MeshBasicNodeMaterial({
    colorNode: mix(
      surfaceColor,
      accentColor,
      uv().x.oneMinus().smoothstep(0.85, 1.0)  // Right edge accent glow
    ),
  });

  const mesh = new THREE.Mesh(geometry, materialNode);
  mesh.position.set(0, 1.6, 0);

  // Load texture and apply once ready
  texturePromise.then((texture) => {
    materialNode.map = texture;
    materialNode.needsUpdate = true;
  });

  // Timeline for hover + click effects
  let hoverTimeline = null;
  let pressTimeline = null;

  const handlers = {
    onHover: () => {
      // Kill any existing hover timeline
      if (hoverTimeline) hoverTimeline.kill();

      // Rise-in: translate +0.15 units on y, settle with overshoot
      hoverTimeline = gsap.timeline();
      hoverTimeline.to(mesh.position, {
        y: 1.75,
        duration: 0.7,
        ease: 'power3.out',
      }, 0);

      // Weighted settle: overshoot 1.04 then settle
      hoverTimeline.to(mesh.scale, {
        x: 1.04,
        y: 1.04,
        duration: 0.3,
        ease: 'back.out',
      }, 0);
      hoverTimeline.to(mesh.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.9,
        ease: 'power4.out',
      }, 0.3);
    },

    onHoverOut: () => {
      if (hoverTimeline) hoverTimeline.kill();
      gsap.to(mesh.position, {
        y: 1.6,
        duration: 0.5,
        ease: 'power2.inOut',
      });
      gsap.to(mesh.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.5,
        ease: 'power2.inOut',
      });
    },

    onClick: () => {
      // Press-down effect: scale 0.97 over 120ms
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.timeline();
      pressTimeline.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
      pressTimeline.to(mesh.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.3,
        ease: 'power2.out',
      });

      // Emit navigation event
      ctx.emit('navigate', { to: 'hub-collection' });
    },
  };

  mesh.userData.handlers = handlers;

  // Cleanup: dispose timelines and materials
  mesh.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    geometry.dispose();
    materialNode.dispose();
  };

  return mesh;
}
